namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();

        foreach (var item in items)
        {
            int orderQuantity = CalculateOrderQuantity(item, season);
            if (orderQuantity <= 0 || string.IsNullOrEmpty(item.Sku))
                continue;

            bool placed = supplier.PlaceOrder(item.Sku, orderQuantity);
            plan.Add(FormatPlanEntry(item.Sku, orderQuantity, placed));
        }

        return plan;
    }

    private static int CalculateOrderQuantity(StockItem item, int season)
    {
        if (item.OnHand < 0)
            return 0;

        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint)
            return 0;

        int deficit = item.ReorderPoint - available;
        int baseQuantity = CalculateBaseQuantity(deficit);
        return ApplySeasonalAdjustment(baseQuantity, season);
    }

    private static int CalculateBaseQuantity(int deficit)
    {
        if (deficit <= 0)
            return 0;
        if (deficit < 10)
            return 10;
        if (deficit < 100)
            return deficit;

        return deficit + 50;
    }

    private static int ApplySeasonalAdjustment(int quantity, int season)
    {
        if (season == 4 && quantity > 0)
            return (int)(quantity * 1.5);
        if (season == 1)
            return quantity / 2;

        return quantity;
    }

    private static string FormatPlanEntry(string sku, int quantity, bool placed)
    {
        if (!placed)
            return $"{sku}:FAILED";

        return quantity > 200
            ? $"{sku}:LARGE:{quantity}"
            : $"{sku}:{quantity}";
    }
}
